  -- editorial route: old-warsaw
  insert into public.routes(city_id,slug,legacy_id,name,description,route_type,owner_user_id,visibility,status,transport,metadata) values(
    v_city,'old-warsaw','old-warsaw','Pierwsze spotkanie z Warszawą','Zamek, Rynek, Barbakan i spokojniejsze Nowe Miasto. Najlepszy początek, jeśli jesteś tu pierwszy raz.','editorial',null,'public','published','walking','{"legacy":{"id":"old-warsaw","name":"Pierwsze spotkanie z Warszawą","description":"Zamek, Rynek, Barbakan i spokojniejsze Nowe Miasto. Najlepszy początek, jeśli jesteś tu pierwszy raz.","stops":["castle","old-town","barbican","new-town"],"cats":["klasyka"]}}'::jsonb
  )
  on conflict(city_id,slug) do update set
    legacy_id=excluded.legacy_id,name=excluded.name,description=excluded.description,route_type='editorial',owner_user_id=null,visibility='public',status='published',transport=excluded.transport,metadata=excluded.metadata
  returning id into v_route;

  delete from public.route_stops where route_id=v_route;
  delete from public.route_tags where route_id=v_route;
  insert into public.route_stops(route_id,place_id,position)
  select v_route,p.id,0 from public.places p where p.city_id=v_city and p.slug='castle';
  if not found then raise exception 'Missing Warsaw place castle for route old-warsaw'; end if;
  insert into public.route_stops(route_id,place_id,position)
  select v_route,p.id,1 from public.places p where p.city_id=v_city and p.slug='old-town';
  if not found then raise exception 'Missing Warsaw place old-town for route old-warsaw'; end if;
  insert into public.route_stops(route_id,place_id,position)
