-- Parity checks. These raise if the generated import is incomplete.
do $$
declare
  v_city uuid;
  place_count integer;
  route_count integer;
begin
  select id into v_city from public.cities where slug='warsaw';
  select count(*) into place_count from public.places where city_id=v_city and status='published';
  select count(*) into route_count from public.routes where city_id=v_city and route_type='editorial' and status='published';
  if place_count < 50 then raise exception 'Warsaw place parity failed: got %, expected at least 50',place_count; end if;
  if route_count < 12 then raise exception 'Warsaw route parity failed: got %, expected at least 12',route_count; end if;
end $$;
